#rf-root,.hf-root{--x3:#d8d1c5;font-family:var(--rf-font);color:var(--rf-text)}.stage{position:absolute;inset:0;animation:st-fadein 0.5s ease-out both,st-pushout 0.5s cubic-bezier(.76,0,.24,1) 5.5s both;}.cam{position:absolute;inset:0;animation:st-cam 6s linear both;}@keyframes st-cam{from{transform:scale(1)}to{transform:scale(1.02)}}.bd{position:absolute;inset:0;overflow:hidden;background:var(--rf-bg)}.bd-grid{position:absolute;inset:0;background-image:linear-gradient(color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px),linear-gradient(90deg,color-mix(in srgb,var(--rf-text) 6%,transparent) 2px,transparent 2px);background-size:108px 108px;background-position:-2px -2px}.tx{position:absolute;inset:0;background:var(--rf-surface);z-index:50}@keyframes st-rise{from{transform:translateY(120px)}to{transform:none}}
@keyframes st-pushin{from{transform:translateX(100%)}to{transform:none}}
@keyframes st-pushout{to{transform:translateX(-100%)}}
@keyframes st-zoomin{from{transform:scale(.92);opacity:0}to{transform:none;opacity:1}}
@keyframes st-zoomout{to{transform:scale(1.08);opacity:0}}
@keyframes st-fadein{from{opacity:0}to{opacity:1}}
@keyframes st-fadeout{to{opacity:0}}.rise{animation:k-rise .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-rise{from{opacity:0;transform:translateY(40px)}to{opacity:1;transform:none}}
.pop{animation:k-pop .7s cubic-bezier(.16,1,.3,1) both}@keyframes k-pop{from{opacity:0;transform:scale(.94)}to{opacity:1;transform:none}}
.slide-l{animation:k-sl .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sl{from{opacity:0;transform:translateX(-80px)}to{opacity:1;transform:none}}
.slide-r{animation:k-sr .8s cubic-bezier(.16,1,.3,1) both}@keyframes k-sr{from{opacity:0;transform:translateX(80px)}to{opacity:1;transform:none}}
.fade{animation:k-fade .8s ease-out both}@keyframes k-fade{from{opacity:0}to{opacity:1}}.mk-l{display:block}.mk-w{display:inline-block;overflow:hidden;vertical-align:top;padding:0 .02em .08em;margin-bottom:-.08em}
.mk-w>span{display:inline-block;animation:mk-up 0.9s cubic-bezier(.16,1,.3,1) both}
@keyframes mk-up{from{transform:translateY(105%)}to{transform:none}}.br-hd{position:absolute;left:90px;right:90px;top:300px;font-size:92px;font-weight:var(--rf-heading-weight);letter-spacing:-.04em;line-height:1}
.br{position:absolute;left:60px;right:60px;top:620px;height:900px;border-radius:36px;background:var(--rf-surface);box-shadow:0 40px 80px -40px rgba(0,0,0,.6),0 0 0 2px color-mix(in srgb,var(--rf-text) 10%,transparent);overflow:hidden;animation:br-in 1s cubic-bezier(.16,1,.3,1) 0.35s both}
@keyframes br-in{from{transform:translateY(160px);opacity:0}}
.br-bar{height:72px;display:flex;align-items:center;gap:12px;padding:0 28px;background:color-mix(in srgb,var(--rf-text) 6%,transparent)}
.br-bar i{width:20px;height:20px;border-radius:50%;background:color-mix(in srgb,var(--rf-text) 25%,transparent)}
.br-bar span{margin-left:24px;padding:8px 24px;border-radius:12px;background:color-mix(in srgb,var(--rf-bg) 60%,transparent);font:500 24px/1.2 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;color:var(--rf-muted)}
.br-body{display:flex;height:calc(100% - 72px)}
.br-side{width:120px;padding:30px 0;display:flex;flex-direction:column;align-items:center;gap:34px;border-right:2px solid color-mix(in srgb,var(--rf-text) 7%,transparent)}
.br-side b{width:44px;height:12px;border-radius:6px;background:color-mix(in srgb,var(--rf-text) 18%,transparent)}
.br-main{flex:1;padding:40px}
.br-top{display:flex;align-items:center;justify-content:space-between;margin-bottom:30px}
.br-h{font-size:44px;font-weight:600;letter-spacing:-.02em}
.br-btn{padding:20px 30px;border-radius:18px;background:var(--rf-accent);color:var(--rf-bg);font-weight:600;font-size:28px;animation:bp .35s ease-out both}
@keyframes bp{0%{transform:scale(1)}40%{transform:scale(.92)}100%{transform:scale(1)}}
.br-row{display:flex;align-items:center;gap:22px;padding:24px;margin-bottom:16px;border-radius:22px;background:color-mix(in srgb,var(--rf-text) 5%,transparent)}
.br-av{width:56px;height:56px;border-radius:16px;flex:none}
.br-t{flex:1;font-size:30px;font-weight:600}
.br-pill{font:500 22px/1 "JetBrains Mono", "DejaVu Sans Mono", "Liberation Mono", monospace;padding:12px 18px;border-radius:10px;background:color-mix(in srgb,var(--rf-text) 8%,transparent);color:var(--rf-muted)}
.br-pill.go{background:color-mix(in srgb,var(--rf-text) 12%,transparent);color:var(--rf-muted);animation:pg .01s step-end both}
@keyframes pg{to{background:color-mix(in srgb,var(--rf-accent) 22%,transparent);color:var(--rf-text)}}
.br-toast{position:absolute;left:50%;bottom:40px;display:flex;align-items:center;gap:16px;transform:translateX(-50%);padding:24px 36px;border-radius:24px;background:var(--rf-text);color:var(--rf-bg);font-size:30px;font-weight:600;white-space:nowrap;animation:bt .6s cubic-bezier(.16,1,.3,1) both}
@keyframes bt{from{transform:translate(-50%,140px);opacity:0}}
.cur{position:absolute;left:0;top:0;z-index:10;animation:cm 1.1s cubic-bezier(.76,0,.24,1) both}
@keyframes cm{from{transform:translate(860px,1700px)}to{transform:translate(830px,790px)}}
.rip{position:absolute;left:-30px;top:-30px;width:60px;height:60px;border-radius:50%;border:4px solid var(--rf-accent);opacity:0;animation:rp .7s ease-out both}
@keyframes rp{from{transform:scale(.3);opacity:1}to{transform:scale(2.6);opacity:0}}

